using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Inventory.Domain;
public sealed class MovementType:Entity<short>{private MovementType(){}private MovementType(short id,string code,string name,bool requiresSource,bool requiresDestination){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));if(!requiresSource&&!requiresDestination)throw new ArgumentException("A movement endpoint is required.");Id=id;Code=InventoryRules.Text(code,40);Name=InventoryRules.Text(name,100);RequiresSource=requiresSource;RequiresDestination=requiresDestination;IsActive=true;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public bool RequiresSource{get;private set;}public bool RequiresDestination{get;private set;}public bool IsActive{get;private set;}public static MovementType Create(short id,string code,string name,bool requiresSource,bool requiresDestination)=>new(id,code,name,requiresSource,requiresDestination);}
